            "source_unit_ids":["u1","u3","u9","u17"],
            "type":"bool",
            "unit":"Boolean classification of one submission event"
          },
          {
            "meaning":"Gregorian calendar date on which the evaluated application or submission is made to IPD.",
            "name":"submission_date",
            "requires_judgment":false,
            "source_unit_ids":["u1","u9"],
            "type":"date",
            "unit":"Gregorian calendar date"
          },
          {
            "meaning":"The evaluated application or submission is submitted to IPD via e-IP.",
            "name":"submitted_via_eip",
